/* amirsalmani/select — the native control, re-skinned.
 *
 * Requires tokens.css and input.css. The chevron is drawn in the mark's own
 * grammar — two straight strokes, round caps — and inherits currentColor via a
 * data URI, so it flips with the ground like everything else.
 */

.as-select {
  width: 100%;
  min-height: 44px;
  padding: .7rem 2.4rem .7rem .9rem;
  border: 1px solid var(--rule);
  border-radius: var(--radius-s);
  background: var(--wash);
  color: var(--fg);
  font-family: var(--sans);
  font-size: 1rem;
  line-height: 1.4;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%, currentColor calc(50% + 1.4px), transparent calc(50% + 1.4px)),
                    linear-gradient(-45deg, transparent 50%, currentColor 50%, currentColor calc(50% + 1.4px), transparent calc(50% + 1.4px));
  background-position: calc(100% - 1.15rem) 55%, calc(100% - .75rem) 55%;
  background-size: .4rem .4rem;
  background-repeat: no-repeat;
  transition: border-color var(--fast) var(--ease-out);
}
.as-select:hover { border-color: var(--glass-edge); }
.as-select:focus { outline: 2px solid var(--accent); outline-offset: 2px; border-color: var(--accent); }
.as-select[disabled] { opacity: .5; cursor: not-allowed; }
.as-select option { background: var(--bg); color: var(--fg); }

@media (prefers-contrast: more) { .as-select { background-color: var(--bg); border-color: var(--fg); } }
